import { describe, expect, it } from "vite-plus/test";

import { findAiAttribution } from "./check-attribution.ts";

// What agents add to commits and PR descriptions, as they write it, and
// what people write that only mentions the tools.

describe(findAiAttribution, () => {
  it("finds AI co-authors, footers and session links", () => {
    const message = [
      "feat(core): add the thing",
      "",
      "Body.",
      "",
      "🤖 Generated with [Claude Code](https://claude.com/claude-code)",
      "---",
      "_Generated by [Claude Code](https://claude.ai/code/session_01AbC)_",
      "https://claude.ai/code/session_01AbC",
      "Co-authored-by: Claude <noreply@anthropic.com>",
      "Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>",
      "Claude-Session: https://claude.ai/code/session_01AbC",
      "Co-authored-by: Jkob <noreply@anthropic.com>",
      "Co-authored-by: Copilot <198982749+Copilot@users.noreply.github.com>",
      "Co-authored-by: Cursor Agent <cursoragent@cursor.com>",
      "> **Generated with Claude Code**",
    ].join("\n");

    expect(findAiAttribution(message).map(({ line }) => line)).toStrictEqual([
      5, 7, 8, 9, 10, 11, 12, 13, 14, 15,
    ]);
  });

  it("leaves people and mentions of the tools alone", () => {
    const message = [
      "fix(core): route Anthropic calls through the gateway",
      "",
      "Anthropic's docs recommend short-term bearer tokens; Claude Code",
      "users read the same. Migrations are generated with `db:generate`.",
      '"models": ["openai/gpt-5.4", "anthropic/claude-sonnet-4-5"]',
      'Remove the "Generated with Claude Code" footer from the template.',
      "",
      "Co-authored-by: Nick <nick@joingrasp.com>",
      "Co-authored-by: Jkob <jakob@joingrasp.com>",
    ].join("\n");

    expect(findAiAttribution(message)).toStrictEqual([]);
  });
});
